// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llamacppimport timber.log.Timber/** * NOUS — Vulkan GPU configuration and detection (v2.1). * * Detects Vulkan availability, VRAM size, and decides whether to use GPU. * Handles context loss gracefully (Android destroys GPU context in background). * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§4 Local LLM</a> */object VulkanConfig {    /**     * Check if Vulkan GPU is available on this device.     *     * @return true if Vulkan is available and native library is loaded     */    fun isVulkanAvailable(): Boolean {        return try {            LlamaCppJni.ensureLoaded() && LlamaCppJni.nativeHasVulkan()        } catch (e: UnsatisfiedLinkError) {            false        } catch (e: Exception) {            false        }    }    /**     * Get available VRAM in MB.     *     * @return VRAM in MB, or 0 if Vulkan unavailable     */    fun getVramMb(): Int {        if (!isVulkanAvailable()) return 0        // In real impl: query Vulkan device properties via JNI        // For now, return a conservative estimate        return estimateVram()    }    /**     * Determine if GPU should be used for LLM inference.     *     * Decision factors:     *   - Vulkan available?     *   - GPU available (DeviceContext.gpuAvailable)?     *   - VRAM >= MIN_VRAM_MB?     *   - Not in thermal throttle?     *     * @param gpuAvailable device GPU flag     * @param thermalStatus device thermal status (0-6)     * @return true if GPU should be used     */    fun shouldUseGpu(        gpuAvailable: Boolean,        thermalStatus: Int = 0,    ): Boolean {        if (!gpuAvailable) {            Timber.tag("NOUS.L4").v("GPU not available on device")            return false        }        if (!isVulkanAvailable()) {            Timber.tag("NOUS.L4").v("Vulkan not available")            return false        }        val vram = getVramMb()        if (vram < MIN_VRAM_MB) {            Timber.tag("NOUS.L4").v("Insufficient VRAM: %dMB < %dMB", vram, MIN_VRAM_MB)            return false        }        // v2.1: Don't use GPU if device is hot (thermal throttling)        if (thermalStatus >= THERMAL_LIMIT_FOR_GPU) {            Timber.tag("NOUS.L4").w("Thermal throttling (status=%d) — GPU disabled", thermalStatus)            return false        }        return true    }    /**     * Check if Vulkan context is still valid after app returns from background.     *     * v2.1: Android destroys GPU context when app goes to deep background.     * This checks if the context survived.     *     * @param modelHandle loaded model handle     * @return true if context is valid, false if needs reload     */    fun isContextValid(modelHandle: Long): Boolean {        if (modelHandle == 0L) return false        return try {            LlamaCppJni.nativeCheckVulkanContext(modelHandle)        } catch (e: Exception) {            false        }    }    /**     * Estimate VRAM based on device.     *     * In production, this would query Vulkan device properties via JNI.     * For now, returns a conservative estimate.     */    private fun estimateVram(): Int {        // Conservative default — real impl queries VkPhysicalDeviceMemoryProperties        return 2048  // 2GB default (most modern GPUs have at least this)    }    /** Minimum VRAM (in MB) required for GPU acceleration. */    const val MIN_VRAM_MB = 1024  // 1GB    /** Thermal status at or above which GPU is disabled (THERMAL_STATUS_SEVERE = 3). */    const val THERMAL_LIMIT_FOR_GPU = 3}